import openpyxl, os, sys
path='/root/output/result.xlsx'
print('Exists:', os.path.exists(path), 'Size:', os.path.getsize(path) if os.path.exists(path) else None)
wb=openpyxl.load_workbook(path, data_only=False)
ws=wb['Task']
print('Key formula cells:')
for addr in ['H12','I12','L17','H19','L24','H26','L31','H35','I36','L40','H42','I43','J44','K45','L46','H47','H50','L50']:
    v=ws[addr].value
    print(f'  {addr}: {v!r} formula={isinstance(v,str) and v.startswith("=")}')
# Check all required cells are nonempty formulas
missing=[]
for row_start,row_end in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(row_start,row_end+1):
        for c in range(8,13):
            v=ws.cell(r,c).value
            if not (isinstance(v,str) and v.startswith('=')):
                missing.append(ws.cell(r,c).coordinate)
print('Missing/non-formula required cells:', missing)
wb.close()
if missing:
    sys.exit(1)
